-- One identity for everything: the app, migrations and people
CREATE USER shop_app FOR LOGIN shop_app;
ALTER ROLE db_owner ADD MEMBER shop_app;

-- The running app: read and write data, nothing else
CREATE USER shop_app FOR LOGIN shop_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON SCHEMA::dbo TO shop_app;

-- The pipeline: schema changes, used only during deployment
CREATE USER shop_migrator FOR LOGIN shop_migrator;
ALTER ROLE db_ddladmin ADD MEMBER shop_migrator;
ALTER ROLE db_datareader ADD MEMBER shop_migrator;
ALTER ROLE db_datawriter ADD MEMBER shop_migrator;

